/** full: everything; quiet: the drawing (lines, legend, pages) but no button, panel or toolbar (D49: the
 *  button feature is off for this student); minimal: only the small dot (off for me); hidden: nothing. */
export type Mode = 'full' | 'quiet' | 'minimal' | 'hidden'

export interface OverlayUi {
  host: HTMLElement
  shadow: ShadowRoot
  layer: HTMLElement
  fab: HTMLButtonElement
  mini: HTMLButtonElement
  panel: HTMLElement
  iframe: HTMLIFrameElement
  mode: Mode
  setFab(text: string, badge?: { text: string; teach?: boolean; off?: boolean } | null): void
  /** full: everything; minimal: only the tiny control (off for me); hidden: nothing at all. */
  setMode(mode: Mode): void
  openPanel(open: boolean): void
  isOpen(): boolean
  toast(text: string, undo?: () => void): void
}

export function buildUi(frameUrl: string, onToggle: (open: boolean) => void, onMini: () => void): OverlayUi {
  const host = document.createElement('div')
  host.className = 'yrS4-host'
  host.setAttribute('data-yrs4', '')
  host.style.cssText = 'position:absolute;top:0;left:0;width:0;height:0;overflow:visible;z-index:2147483000;'
  const shadow = host.attachShadow({ mode: 'open' })
  const style = document.createElement('style')
  style.textContent = CSS_TEXT
  shadow.appendChild(style)
  const layer = document.createElement('div')
  layer.className = 'layer'
  shadow.appendChild(layer)

  const fab = document.createElement('button')
  fab.type = 'button'
  fab.className = 'fab'
  fab.hidden = true                       // shown once the frame says the overlay is on for this reader
  fab.setAttribute('aria-label', 'Open the subjexts panel')
  fab.textContent = 'subjexts'
  shadow.appendChild(fab)

  const mini = document.createElement('button')
  mini.type = 'button'
  mini.className = 'mini'
  mini.hidden = true
  mini.textContent = 's'
  mini.title = 'subjexts is off for you. Click to turn it on.'
  mini.setAttribute('aria-label', mini.title)
  shadow.appendChild(mini)

  const panel = document.createElement('div')
  panel.className = 'panel'
  panel.setAttribute('role', 'complementary')
  panel.setAttribute('aria-label', 'subjexts panel')
  const iframe = document.createElement('iframe')
  iframe.src = frameUrl
  iframe.title = 'subjexts'
  iframe.setAttribute('allow', 'clipboard-write')
  panel.appendChild(iframe)
  shadow.appendChild(panel)
  document.body.appendChild(host)

  let open = false
  const ui: OverlayUi = {
    host, shadow, layer, fab, mini, panel, iframe, mode: 'full',
    setFab(text, badge) {
      fab.replaceChildren(document.createTextNode(text))
      if (badge) {
        const b = document.createElement('span')
        b.className = 'badge' + (badge.teach ? ' teach' : '') + (badge.off ? ' off' : '')
        b.textContent = badge.text
        fab.appendChild(b)
      }
      if (ui.mode === 'full') fab.hidden = false
    },
    setMode(mode) {
      ui.mode = mode
      layer.hidden = mode !== 'full' && mode !== 'quiet'
      fab.hidden = mode !== 'full'
      mini.hidden = mode !== 'minimal'
      if (mode !== 'full') ui.openPanel(false)
    },
    openPanel(o) {
      open = o
      panel.classList.toggle('open', o)
      onToggle(o)
    },
    isOpen: () => open,
    toast(text, undo) {
      const t = document.createElement('div')
      t.className = 'toast'
      t.textContent = text
      if (undo) {
        const b = document.createElement('button')
        b.textContent = 'Undo'
        b.addEventListener('click', () => {
          undo()
          t.remove()
        })
        t.appendChild(b)
      }
      shadow.appendChild(t)
      setTimeout(() => t.remove(), undo ? 6000 : 3000)
    },
  }
  fab.addEventListener('click', () => ui.openPanel(!open))
  mini.addEventListener('click', onMini)
  return ui
}
