// Margin lines (docs/06a-labels.qmd, D36): the only way a mark shows on the page. A thin colored line in the
// left gutter beside the passage, one per mark, side by side when they overlap. Hovering (or focusing) a line
// shows a card with the label names, the date and, for the viewer's own marks, a Remove button. Real elements
// with text, so screen readers and keyboards reach them (docs/03-architecture.qmd).
import type { LabelInfo, MarkRow } from '../../../shared/types.ts'
import type { PaintClass } from './highlights.ts'

export interface Placed {
  mark: MarkRow
  range: Range
  cls: PaintClass
  element?: HTMLElement        // section/page scope
  labels?: LabelInfo[]         // for label marks
  gaps?: Array<{ top: number; bottom: number; label?: string }>   // excepted parts (page coordinates), D38
}

const LABEL: Record<string, string> = {
  covered: 'Covered', assigned: 'Read on your own', skipped: 'Skipped in class', comment: 'Comment',
  note: 'Editorial note', student: 'My highlight', edit: 'My edit', flash: '',
}
export const KIND_COLORS: Record<string, string> = { covered: '#43a047', assigned: '#1e88e5', skipped: '#9e9e9e', comment: '#fb8c00', note: '#8e24aa', student: '#fdd835', edit: '#0d9488' }

export function fmtDate(iso: string | null | undefined): string {
  if (!iso) return ''
  const d = new Date(iso.length === 10 ? iso + 'T12:00:00' : iso)
  return d.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })
}

export function markLabel(p: Placed, dates = true): string {
  const m = p.mark
  const date = dates ? (m.sections[0]?.meets_on ? fmtDate(m.sections[0].meets_on) : fmtDate(m.created_at)) : ''
  const title = m.sections[0]?.meeting_title ? ` (${m.sections[0].meeting_title})` : ''
  if (m.kind === 'label') return `${(p.labels || []).map((l) => l.name).join(', ') || 'Label'}${p.labels?.some((l) => l.kind === 'coverage') ? ` ${date}${title}` : ''}`
  if (m.kind === 'coverage') return `${LABEL[p.cls]} ${date}${title}`
  if (m.kind === 'comment') return `Comment ${date}${title}`
  if (m.kind === 'author_note') return `Editorial note · ${(m.data.category as string) || 'note'}`
  if (m.kind === 'student_note') return m.data.highlight ? 'My highlight' : 'My note'
  if (m.kind === 'suggestion') return m.data.draft && !m.body ? 'My edit (unsaved draft: Edit to resume)' : `My edit${m.status === 'exported' ? ' (exported)' : ''}${m.data.draft_md ? ' · has an unsaved draft' : ''}`
  return LABEL[p.cls] || m.kind
}

export function colorsOf(p: Placed): string[] {
  if (p.labels?.length) return p.labels.map((l) => l.color)
  return [KIND_COLORS[p.cls] || '#9ca3af']
}

export interface CardHandlers {
  open(id: string): void
  edit(id: string): void                     // in-place edits: open the editor
  toggleOriginal(id: string): void           // in-place edits: show the original block for a moment
  remove(id: string): void
  removeLabel(id: string, labelId: string): void
  canEdit(m: MarkRow): boolean
  bubbleHidden?(id: string): boolean         // editorial notes (D53): the bubble was hidden one by one
  showBubble?(id: string): void              // bring it back
}

export class MarginBars {
  showDates = false              // the date on the card and the line's title (B81): the frame decides (OverlayState.showDates)
  private layer: HTMLElement
  private bars = new Map<string, HTMLElement>()
  private card: HTMLElement
  private cardFor: string | null = null
  private hideTimer: number | undefined
  private placed = new Map<string, Placed>()
  constructor(layer: HTMLElement, private h: CardHandlers) {
    this.layer = layer
    this.card = document.createElement('div')
    this.card.className = 'yrS4-card'
    this.card.hidden = true
    this.card.addEventListener('mouseenter', () => this.cancelHide())
    this.card.addEventListener('mouseleave', () => this.scheduleHide())
    layer.appendChild(this.card)
  }

  clear() {
    for (const b of this.bars.values()) b.remove()
    this.bars.clear()
    this.hideCard()
  }

  /** Create or move the lines. Call again on resize / mutation. */
  layout(placed: Placed[], contentRoot: HTMLElement) {
    // The line sits 12 px left of the passage's own text edge (not the content box, which themes pad).
    const rootLeft = contentRoot.getBoundingClientRect().left + window.scrollX
    const seen = new Set<string>()
    this.placed = new Map(placed.map((p) => [p.mark.id, p]))
    // measure, then assign lanes so overlapping lines sit side by side (lane 0 nearest the text)
    const items: Array<{ p: Placed; top: number; bottom: number; left: number; lane: number; labels: LabelInfo[] | undefined; seg: number; split?: boolean }> = []
    for (const p of placed) {
      const rects = p.element ? [p.element.getBoundingClientRect()] : Array.from(p.range.getClientRects())
      if (!rects.length) continue
      const top = Math.min(...rects.map((r) => r.top)) + window.scrollY
      const bottom = Math.max(...rects.map((r) => r.bottom)) + window.scrollY
      if (bottom - top < 2) continue
      // a text range's own left is its first line's; use the block it starts in so lines of one paragraph align
      const startEl = p.element || (p.range.startContainer.nodeType === 1 ? (p.range.startContainer as Element) : p.range.startContainer.parentElement)?.closest('p, li, pre, td, th, figcaption, h1, h2, h3, h4, h5, h6, div, section') || null
      const textLeft = (startEl ? startEl.getBoundingClientRect().left : Math.min(...rects.map((r) => r.left))) + window.scrollX
      const left = Math.max(2, Math.max(rootLeft - 14, textLeft - 12))
      // an exception for every label of the mark cuts the line; one for a single label (of several) doesn't
      const gaps = (p.gaps || []).filter((g) => !g.label || (p.labels || []).length <= 1 || (p.labels || []).every((l) => l.id === g.label)).sort((a, b) => a.top - b.top)
      let cur = top, seg = 0
      for (const g of gaps) {
        if (g.top > cur + 2) items.push({ p, top: cur, bottom: Math.min(g.top, bottom), left, lane: 0, labels: p.labels, seg: seg++ })
        cur = Math.max(cur, g.bottom)
      }
      if (bottom > cur + 2 || !gaps.length) items.push({ p, top: cur, bottom, left, lane: 0, labels: p.labels, seg })
    }
    items.sort((a, b) => a.top - b.top || b.bottom - a.bottom)
    // A label mark inside a larger one with the same label draws no line of its own (8.3.1 inside 8.3, both
    // "Covered"): only the labels the enclosing lines don't already show are drawn; none left, no line.
    for (let i = 0; i < items.length; i++) {
      const it = items[i]
      if (it.p.mark.kind !== 'label' || !it.labels?.length) continue
      const shownAbove = new Set<string>()
      for (let j = 0; j < i; j++) {
        const o = items[j]
        if (o.p.mark.kind !== 'label' || o.p.mark.id === it.p.mark.id) continue
        if (o.top <= it.top + 1 && o.bottom >= it.bottom - 1 && (o.bottom - o.top > it.bottom - it.top + 1 || j < i)) for (const l of o.labels || []) shownAbove.add(l.id)
      }
      it.labels = it.labels.filter((l) => !shownAbove.has(l.id))
    }
    // A mark with two to four labels draws one line per label, side by side (B82); five or more, one striped line.
    const draw: typeof items = []
    for (const it of items) {
      if (it.p.mark.kind === 'label' && it.labels && it.labels.length >= 2 && it.labels.length <= 4) for (const l of it.labels) draw.push({ ...it, labels: [l], split: true })
      else draw.push(it)
    }
    const laneEnds: number[] = []
    for (const it of draw) {
      if (it.p.mark.kind === 'label' && it.labels && !it.labels.length) continue
      let lane = 0
      while (lane < laneEnds.length && laneEnds[lane] > it.top + 1) lane++
      it.lane = Math.min(lane, 5)
      laneEnds[it.lane] = Math.max(laneEnds[it.lane] || 0, it.bottom)
    }
    for (const it of draw) {
      const p = it.p
      if (p.mark.kind === 'label' && it.labels && !it.labels.length) continue   // fully covered by an enclosing line
      const key = `${p.mark.id}#${it.seg}${it.split ? '#' + it.labels![0].id : ''}`
      seen.add(key)
      let bar = this.bars.get(key)
      if (!bar) {
        const b = document.createElement('button')
        b.type = 'button'
        bar = b
        bar.setAttribute('data-id', p.mark.id)
        bar.addEventListener('click', (e) => {
          e.preventDefault()
          this.at = { bar: bar!, y: e.pageY }
          this.showCard(p.mark.id, true)
        })
        bar.addEventListener('mouseenter', (e) => { this.at = { bar: bar!, y: e.pageY }; this.hoverCard(p.mark.id) })
        bar.addEventListener('mouseleave', () => { this.cancelSwitch(); this.scheduleHide() })
        bar.addEventListener('focus', () => this.showCard(p.mark.id, false))
        bar.addEventListener('blur', () => this.scheduleHide())
        this.layer.appendChild(bar)
        this.bars.set(key, bar)
      }
      const label = markLabel(p, this.showDates) + (p.mark.body && p.mark.kind !== 'author_note' ? `: ${p.mark.body.slice(0, 140)}` : '')
      bar.setAttribute('aria-label', label)
      bar.title = ''
      bar.style.top = `${it.top}px`
      bar.style.height = `${Math.max(12, it.bottom - it.top)}px`
      bar.style.left = `${it.left - it.lane * 5}px`
      bar.className = `yrS4-bar yrS4-bar-${p.cls}${p.mark.kind === 'comment' ? ' yrS4-bar-text' : ''}${p.mark.kind === 'author_note' ? ' yrS4-bar-dotted' : ''}`
      bar.setAttribute('data-labels', (it.labels || []).map((l) => l.id).join(' ') || p.cls)
      const cols = colorsOf({ ...p, labels: it.labels })
      bar.style.background = cols.length > 1 ? `repeating-linear-gradient(0deg, ${cols.map((c, i) => `${c} ${i * 6}px ${i * 6 + 6}px`).join(', ')})` : cols[0]
      if (p.labels?.[0]?.style === 'dotted' || p.mark.kind === 'author_note') bar.style.backgroundImage = `repeating-linear-gradient(0deg, ${cols[0]} 0 3px, transparent 3px 6px)`
    }
    for (const [key, bar] of this.bars) {
      if (!seen.has(key)) {
        bar.remove()
        this.bars.delete(key)
        if (this.cardFor === key.split('#')[0] && ![...this.bars.keys()].some((k) => k.startsWith(`${this.cardFor}#`))) this.hideCard()
      }
    }
    if (this.cardFor && this.placed.has(this.cardFor)) this.placeCard()
  }

  // --- the hover card ----------------------------------------------------------------------------------------------
  private scheduleHide() {
    this.cancelHide()
    this.hideTimer = window.setTimeout(() => this.hideCard(), 350)
  }
  /** The mouse on a line: its card at once, unless another mark's card is up, which a line crossed on the way to
   *  the card would otherwise replace (B82): then only after the mouse rests on the line. */
  private switchTimer: number | undefined
  private at: { bar: HTMLElement; y: number } | null = null   // the line the mouse is on, and where: the card sits beside that spot (B83)
  private hoverCard(id: string) {
    this.cancelHide()
    if (this.card.hidden || this.cardFor === id || this.cardFor === null) return this.showCard(id, false)
    this.cancelSwitch()
    this.switchTimer = window.setTimeout(() => this.showCard(id, false), 300)
  }
  private cancelSwitch() {
    if (this.switchTimer) clearTimeout(this.switchTimer)
    this.switchTimer = undefined
  }
  private cancelHide() {
    if (this.hideTimer) clearTimeout(this.hideTimer)
    this.hideTimer = undefined
  }
  hideCard() {
    this.card.hidden = true
    this.cardFor = null
  }
  /** Re-render the open card (after a label was removed). */
  refreshCard() {
    if (this.cardFor) this.showCard(this.cardFor, false)
  }

  private showCard(id: string, pinned: boolean) {
    this.cancelHide()
    const p = this.placed.get(id)
    if (!p) return this.hideCard()
    this.cardFor = id
    const m = p.mark
    this.card.replaceChildren()
    const editable = this.h.canEdit(m)
    const head = document.createElement('div')
    head.className = 'yrS4-card-head'
    if (m.kind === 'label' && p.labels?.length) {
      for (const l of p.labels) {
        const chip = document.createElement('span')
        chip.className = 'yrS4-chip static'
        chip.style.setProperty('--c', l.color)
        chip.innerHTML = '<span class="yrS4-chip-dot"></span><span class="yrS4-chip-name"></span>'
        chip.querySelector('.yrS4-chip-name')!.textContent = l.name + (l.hides ? ' (hidden from students and visitors)' : '')
        if (editable) {
          const x = document.createElement('button')
          x.type = 'button'
          x.className = 'yrS4-chip-x'
          x.textContent = '×'
          x.title = `Remove "${l.name}" from this passage`
          x.setAttribute('aria-label', x.title)
          x.addEventListener('click', (e) => {
            e.stopPropagation()
            this.h.removeLabel(m.id, l.id)
          })
          chip.appendChild(x)
        }
        head.appendChild(chip)
      }
    } else {
      const k = document.createElement('strong')
      k.textContent = markLabel(p, this.showDates)
      k.style.color = colorsOf(p)[0]
      head.appendChild(k)
    }
    this.card.appendChild(head)
    const meta = document.createElement('div')
    meta.className = 'yrS4-card-meta'
    const date = this.showDates ? (m.sections[0]?.meets_on ? fmtDate(m.sections[0].meets_on) : fmtDate(m.created_at)) : ''
    const title = this.showDates && m.sections[0]?.meeting_title ? ` · ${m.sections[0].meeting_title}` : ''
    const where = (p.element && m.anchor?.scope === 'page') ? 'whole page' : m.anchor?.scope === 'section' ? `section: ${m.anchor.section?.headings.slice(-1)[0] || ''}` : m.anchor?.scope === 'block' ? 'this block' : 'this passage'
    const exc = ((m.data.except as Array<{ title?: string }> | undefined) || []).map((x) => x.title).filter(Boolean)
    // data.via reaches the page only for the mark's own author (the frame strips it otherwise, D47)
    const via = m.data.via ? ' · from the command line' : ''
    meta.textContent = `${where}${exc.length ? ` (except ${exc.join(', ')})` : ''}${date ? ` · ${date}` : ''}${title}${via}`
    this.card.appendChild(meta)
    if (m.body && m.kind !== 'author_note' && m.kind !== 'suggestion') {
      const b = document.createElement('div')
      b.className = 'yrS4-card-body'
      b.textContent = m.body.length > 220 ? m.body.slice(0, 220) + '…' : m.body
      this.card.appendChild(b)
    }
    if (m.kind === 'suggestion') {
      const b = document.createElement('div')
      b.className = 'yrS4-card-meta'
      b.textContent = 'Shown in place of the original, to you only. The book\'s source is unchanged until the proposal is applied.'
      this.card.appendChild(b)
    }
    const acts = document.createElement('div')
    acts.className = 'yrS4-card-acts'
    if (m.kind === 'suggestion' && editable) {
      const ed = document.createElement('button')
      ed.type = 'button'
      ed.className = 'yrS4-tb small'
      ed.textContent = 'Edit'
      ed.addEventListener('click', () => {
        this.hideCard()
        this.h.edit(m.id)
      })
      acts.appendChild(ed)
      const orig = document.createElement('button')
      orig.type = 'button'
      orig.className = 'yrS4-tb small'
      orig.textContent = 'Original'
      orig.title = 'Show the original text while this is pressed'
      orig.addEventListener('mousedown', () => this.h.toggleOriginal(m.id))
      orig.addEventListener('mouseup', () => this.h.toggleOriginal(m.id))
      orig.addEventListener('mouseleave', () => this.h.toggleOriginal(m.id))
      acts.appendChild(orig)
    }
    const open = document.createElement('button')
    open.type = 'button'
    open.className = 'yrS4-tb small'
    open.textContent = m.kind === 'comment' || m.kind === 'author_note' || m.kind === 'message' ? 'Open' : 'Details'
    open.addEventListener('click', () => {
      this.hideCard()
      this.h.open(m.id)
    })
    acts.appendChild(open)
    if (m.kind === 'author_note' && this.h.bubbleHidden?.(m.id)) {
      const sb = document.createElement('button')
      sb.type = 'button'
      sb.className = 'yrS4-tb small'
      sb.textContent = 'Show bubble'
      sb.title = 'The note\'s bubble beside the text was hidden; show it again'
      sb.addEventListener('click', () => {
        this.hideCard()
        this.h.showBubble?.(m.id)
      })
      acts.appendChild(sb)
    }
    if (editable) {
      const rm = document.createElement('button')
      rm.type = 'button'
      rm.className = 'yrS4-tb small danger'
      rm.textContent = m.kind === 'label' ? 'Remove all' : m.kind === 'suggestion' ? 'Discard edit' : 'Delete'
      rm.addEventListener('click', () => {
        this.hideCard()
        this.h.remove(m.id)
      })
      acts.appendChild(rm)
    }
    this.card.appendChild(acts)
    this.card.hidden = false
    this.placeCard()
    if (pinned) this.card.querySelector<HTMLElement>('button')?.focus({ preventScroll: true })
  }

  private placeCard() {
    if (!this.cardFor) return
    // beside the line the mouse is on (a mark with several labels has several lines; B82), else the mark's first line
    const own = this.at && this.at.bar.getAttribute('data-id') === this.cardFor && this.at.bar.isConnected ? this.at.bar : undefined
    const bar = own || [...this.bars.entries()].find(([k]) => k.startsWith(`${this.cardFor}#`))?.[1]
    if (!bar) return
    const barTop = parseFloat(bar.style.top), barH = parseFloat(bar.style.height) || 12
    // at the pointer's height on a long line (a section), so the card is next to the spot, not far above it
    const top = own && this.at ? Math.min(Math.max(this.at.y - 10, barTop), barTop + barH - 20) : barTop
    const left = parseFloat(bar.style.left)
    const w = this.card.offsetWidth || 260
    let x = left + 12
    const vw = document.documentElement.clientWidth
    if (x + w > window.scrollX + vw - 8) x = Math.max(8, window.scrollX + vw - w - 8)
    this.card.style.left = `${x}px`
    this.card.style.top = `${top}px`
  }
}
