// Block checkboxes (docs/06a-labels.qmd, D36): in Teach mode a checkbox sits in the left gutter beside every
// section heading (a square) and every block of text (a smaller circle). Checked = the block carries a label.
// Clicking opens the label popover for that block; Shift+click applies the current label at once.
import type { LabelInfo } from '../../../shared/types.ts'
import type { HeadingInfo } from '../adapters/index.ts'

export interface BlockTarget {
  kind: 'section' | 'block'
  element: HTMLElement          // the heading's section element, or the block
  heading?: HeadingInfo
  title: string                 // "Section: Git vs. GitHub" / "Paragraph" / "Code block"
}
export interface Inherited { label: LabelInfo; markId: string; from: string }   // from: "section 8.4" / "the page"
export interface BlockState {
  labels: LabelInfo[]           // labels applied to exactly this block/section (own marks)
  partial: boolean              // some text inside is marked, but not the whole block
  inherited: Inherited[]        // labels this block has because an enclosing section or the page carries them (D38)
  excluded: Inherited[]         // enclosing labels this block is excepted from
}

/** Blocks that get a checkbox: the outermost of these inside the content root. */
export const BLOCK_SELECTOR = 'p, pre, ul, ol, table, figure, blockquote, div.cell, div.cell_input, div.highlight'
const SKIP_INSIDE = '[data-yrs4], nav, #TOC, #title-block-header, .quarto-title-block, .callout-header, .yrS4-legend, header, footer, .bd-toc'

export function blockTitle(el: HTMLElement): string {
  const t = el.tagName.toLowerCase()
  if (el.matches('pre, div.cell, div.cell_input, div.highlight')) return 'Code block'
  return t === 'p' ? 'Paragraph' : t === 'ul' || t === 'ol' ? 'List' : t === 'table' ? 'Table' : t === 'figure' ? 'Figure' : t === 'blockquote' ? 'Quote' : 'Block'
}

/** Every checkable block of the page, in document order (sections first where a heading starts one). */
export function findBlocks(root: HTMLElement, headings: HeadingInfo[]): BlockTarget[] {
  const out: BlockTarget[] = []
  for (const h of headings) out.push({ kind: 'section', element: h.section, heading: h, title: `Section: ${h.text}` })
  for (const el of Array.from(root.querySelectorAll<HTMLElement>(BLOCK_SELECTOR))) {
    if (el.closest(SKIP_INSIDE)) continue
    const outer = el.parentElement?.closest(BLOCK_SELECTOR)
    if (outer && root.contains(outer)) continue                      // nested: the outer block has the box
    if (!(el.textContent || '').trim() && !el.querySelector('img, table')) continue
    out.push({ kind: 'block', element: el, title: blockTitle(el) })
  }
  return out
}

/** The target that holds `el`: the section whose heading `el` is in, else the outermost block of `targets`
 *  around `el`. `closest(BLOCK_SELECTOR)` alone finds the innermost block, which in a nested block (a Jupyter
 *  Book cell: div.cell > div.cell_input > div.highlight > pre; a list: ul > li > p) has no box (B73). */
export function targetAt(el: Element | null | undefined, targets: BlockTarget[]): BlockTarget | undefined {
  if (!el) return undefined
  const h = el.closest('h1, h2, h3, h4, h5, h6')
  if (h) {
    const t = targets.find((x) => x.heading?.element === h)
    if (t) return t
  }
  for (let b = el.closest(BLOCK_SELECTOR); b; b = b.parentElement?.closest(BLOCK_SELECTOR) || null) {
    const t = targets.find((x) => x.kind === 'block' && x.element === b)
    if (t) return t
  }
  return undefined
}

export class BlockBoxes {
  private boxes = new Map<HTMLElement, HTMLButtonElement>()
  private enabled = false
  targets: BlockTarget[] = []
  private picked = new Set<HTMLElement>()
  constructor(private layer: HTMLElement, private onClick: (t: BlockTarget, box: HTMLElement, pick: boolean) => void) {}

  /** The boxes picked with Shift/Ctrl+click (D52) get a ring. */
  setPicked(elements: Set<HTMLElement>) {
    this.picked = elements
    for (const [el, box] of this.boxes) box.classList.toggle('yrS4-picked', elements.has(el))
  }

  setEnabled(on: boolean) {
    this.enabled = on
    if (!on) this.clear()
  }
  get isEnabled() {
    return this.enabled
  }
  clear() {
    for (const b of this.boxes.values()) b.remove()
    this.boxes.clear()
  }

  /** Create or move the boxes; `stateOf` says what each block carries. */
  layout(targets: BlockTarget[], contentRoot: HTMLElement, stateOf: (t: BlockTarget) => BlockState) {
    this.targets = targets
    if (!this.enabled) return
    // Beside the text, not the content box: themes pad the article (Jupyter Book), so use each element's own left.
    void contentRoot
    const seen = new Set<HTMLElement>()
    for (const t of targets) {
      const el = t.kind === 'section' ? t.heading!.element : t.element
      const r = el.getBoundingClientRect()
      if (!r.height) continue
      seen.add(t.element)
      let box = this.boxes.get(t.element)
      if (!box) {
        box = document.createElement('button')
        box.type = 'button'
        box.addEventListener('click', (e) => {
          e.preventDefault()
          e.stopPropagation()
          this.onClick(t, box!, e.shiftKey || e.ctrlKey || e.metaKey)
        })
        this.layer.appendChild(box)
        this.boxes.set(t.element, box)
      }
      const st = stateOf(t)
      const on = st.labels.length > 0
      const inh = st.inherited.filter((x) => !st.excluded.some((e) => e.markId === x.markId && e.label.id === x.label.id))
      const excluded = !on && st.excluded.length > 0 && inh.length === 0
      const inherited = !on && !excluded && inh.length > 0
      box.className = `yrS4-box yrS4-box-${t.kind}${this.picked.has(t.element) ? ' yrS4-picked' : ''}${on ? ' on' : ''}${inherited ? ' inherited' : ''}${excluded ? ' excluded' : ''}${st.partial && !on && !inherited && !excluded ? ' partial' : ''}`
      box.setAttribute('aria-pressed', on || inherited ? 'true' : 'false')
      const names = st.labels.map((l) => l.name).join(', ')
      box.title = on ? `${t.title}: ${names}. Click to change`
        : inherited ? `${t.title}: ${inh.map((x) => `${x.label.name} (from ${x.from})`).join(', ')}. Click to except it`
        : excluded ? `${t.title}: excepted from ${st.excluded.map((x) => `${x.label.name} (${x.from})`).join(', ')}. Click to include it again`
        : st.partial ? `${t.title}: part of it is labeled. Click to label all of it` : `${t.title}: click for the menu (Shift+click or Ctrl+click: pick several)`
      box.setAttribute('aria-label', box.title)
      const first = st.labels[0] || inh[0]?.label || st.excluded[0]?.label
      box.style.setProperty('--c', first?.color || '#9ca3af')
      if (on && st.labels.length > 1) box.style.setProperty('--c2', st.labels[1].color)
      else box.style.removeProperty('--c2')
      const size = t.kind === 'section' ? 14 : 11
      const lineH = t.kind === 'section' ? Math.min(r.height, 32) : Math.min(r.height, 24)
      box.style.left = `${Math.max(2, r.left + window.scrollX - (t.kind === 'section' ? 32 : 30))}px`
      box.style.top = `${r.top + window.scrollY + lineH / 2 - size / 2}px`
      box.style.width = box.style.height = `${size}px`
    }
    for (const [el, box] of this.boxes) {
      if (!seen.has(el)) {
        box.remove()
        this.boxes.delete(el)
      }
    }
  }

  boxFor(el: HTMLElement): HTMLElement | undefined {
    return this.boxes.get(el)
  }
}
