// From a selection (or a heading, or the page) to an anchor (docs/04-anchoring.qmd).
import type { Anchor } from '../../../shared/types.ts'
import type { BookAdapter, HeadingInfo } from '../adapters/index.ts'
import { domToRaw, rawToNormOffset, type PageText } from './text.ts'

export const CONTEXT = 32

export interface DescribeOptions {
  pkg: string
  page: string
  build: string | null
  adapter: BookAdapter
  headings: HeadingInfo[]
  generatedSelectors: string[]   // elements whose text was made by scripts after load
}

/** Heading path above `el`: nearest heading first by document position, then its ancestors by level. */
export function headingPath(el: Node, headings: HeadingInfo[]): { id: string; headings: string[] } | undefined {
  const pos = (h: HeadingInfo) => h.element.compareDocumentPosition(el)
  let nearest: HeadingInfo | undefined
  for (const h of headings) {
    const p = pos(h)
    if (p & Node.DOCUMENT_POSITION_FOLLOWING || h.element.contains(el)) nearest = h
    else break
  }
  if (!nearest) return undefined
  const path: string[] = [nearest.text]
  let level = nearest.level
  for (let i = headings.indexOf(nearest) - 1; i >= 0 && level > 1; i--) {
    if (headings[i].level < level) {
      path.unshift(headings[i].text)
      level = headings[i].level
    }
  }
  return { id: nearest.id, headings: path }
}

function isGenerated(node: Node, selectors: string[]): boolean {
  const el = node.nodeType === 1 ? (node as Element) : node.parentElement
  if (!el || !selectors.length) return false
  try {
    return !!el.closest(selectors.join(', '))
  } catch {
    return false
  }
}

export function describeRange(range: Range, pt: PageText, o: DescribeOptions): Anchor | { error: string } {
  const rs = domToRaw(pt, range.startContainer, range.startOffset)
  const re = domToRaw(pt, range.endContainer, range.endOffset)
  let start = rawToNormOffset(pt, rs)
  let end = rawToNormOffset(pt, re)
  // trim whitespace at the ends
  while (start < end && pt.text[start] === ' ') start++
  while (end > start && pt.text[end - 1] === ' ') end--
  if (end <= start) return { error: 'Select some of the book\'s text first.' }
  const exact = pt.text.slice(start, end)
  if (isGenerated(range.startContainer, o.generatedSelectors) && isGenerated(range.endContainer, o.generatedSelectors)) {
    return { error: 'That text is produced by the page\'s scripts, so a mark can\'t be attached to it.' }
  }
  const prefix = pt.text.slice(Math.max(0, start - CONTEXT), start)
  const suffix = pt.text.slice(end, Math.min(pt.text.length, end + CONTEXT))
  const startNode = range.startContainer
  const kind = o.adapter.blockKind(startNode)
  const endKind = o.adapter.blockKind(range.endContainer)   // a selection from prose into code says so (D51)
  const kinds = endKind !== kind ? [kind, endKind] : undefined
  const el = startNode.nodeType === 1 ? (startNode as Element) : startNode.parentElement
  const block = el?.closest('p, li, pre, td, th, figcaption, h1, h2, h3, h4, h5, h6, div') || null
  return {
    package: o.pkg,
    page: o.page,
    section: headingPath(startNode, o.headings),
    quote: { exact, prefix, suffix },
    position: { start, end },
    scope: 'text',
    block: { kind, ...(kinds ? { kinds } : {}), selector: block ? block.tagName.toLowerCase() : undefined },
    build: o.build || 'local',
  }
}

/** A whole block (paragraph, list, code block…): its full text as the quote, scope 'block' (D36). */
export function describeBlock(el: HTMLElement, pt: PageText, o: DescribeOptions): Anchor | { error: string } {
  const r = document.createRange()
  r.selectNodeContents(el)
  const a = describeRange(r, pt, o)
  if ('error' in a) return a
  return { ...a, scope: 'block', block: { kind: o.adapter.blockKind(el), selector: el.tagName.toLowerCase() } }
}

export function describeSection(h: HeadingInfo, o: DescribeOptions): Anchor {
  const path = headingPath(h.element, o.headings)
  return {
    package: o.pkg,
    page: o.page,
    section: { id: h.id, headings: path?.headings || [h.text] },
    scope: 'section',
    build: o.build || 'local',
  }
}

export function describePage(o: DescribeOptions, title: string): Anchor {
  return { package: o.pkg, page: o.page, section: { id: '', headings: [title] }, scope: 'page', build: o.build || 'local' }
}
