// Note bubbles (docs/07-author-notes.qmd, D53): an editorial note's text in a callout beside the passage it is on,
// with a pointer to the passage and a light tint over the passage in the note's color. The author's request of
// 2026-11-04: read the notes in the text, not only on hover. The bubbles sit in the right margin, stacked so
// they never overlap, and each one can hide itself ("Hide") or all of them ("Hide all"); the switch in the panel
// ("as bubbles beside the text", under "Show my editorial notes") brings them back. The tint is drawn in the
// overlay layer over the passage's rectangles, like the menu's tint (D51): the book's text is not painted.
// Everything lives in the shadow root, in page coordinates, like the margin lines.
import type { MarkRow } from '../../../shared/types.ts'
import type { Placed } from './margin.ts'

export const BUBBLE_CSS = `
/* note bubbles (D53) */
.yrS4-bubbles { position: absolute; left: 0; top: 0; width: 0; height: 0; overflow: visible; }
.yrS4-bubbles[hidden] { display: none; }
.yrS4-bubble-tint { position: absolute; pointer-events: none; background: rgba(142, 36, 170, .11); border-radius: 3px; transition: background .12s; }
.yrS4-bubble-tint.hot { background: rgba(142, 36, 170, .24); box-shadow: 0 0 0 1px rgba(142, 36, 170, .35); }
.yrS4-bubble-wire { position: absolute; pointer-events: none; border-top: 1px dashed rgba(142, 36, 170, .55); }
.yrS4-bubble-drop { position: absolute; pointer-events: none; border-left: 1px dashed rgba(142, 36, 170, .55); }
.yrS4-bubble { position: absolute; width: 250px; background: #fdf8ff; color: #1f2937; border: 1px solid #d8b4e2; border-left: 3px solid #8e24aa; border-radius: 7px; box-shadow: 0 3px 12px rgba(0,0,0,.14); padding: 6px 8px 6px 9px; font-size: 12px; line-height: 1.4; display: flex; flex-direction: column; gap: 4px; z-index: 2147483000; }
.yrS4-bubble::before { content: ""; position: absolute; left: -11px; top: 9px; border: 6px solid transparent; border-right-color: #8e24aa; border-left: 0; }
.yrS4-bubble.left::before { left: auto; right: -9px; border: 6px solid transparent; border-left-color: #d8b4e2; border-right: 0; }
.yrS4-bubble.inside::before { display: none; }
.yrS4-bubble.inside { opacity: .96; }
.yrS4-bubble:hover, .yrS4-bubble.hot { border-color: #8e24aa; box-shadow: 0 4px 16px rgba(142, 36, 170, .3); }
.yrS4-bubble-head { display: flex; align-items: baseline; gap: 6px; font-size: 11px; color: #6b21a8; }
.yrS4-bubble-kind { font-weight: 600; }
.yrS4-bubble-prio { letter-spacing: 1px; color: #a855f7; }
.yrS4-bubble-x { margin-left: auto; border: 0; background: transparent; color: #9ca3af; font: inherit; font-size: 15px; line-height: 1; padding: 0 2px; cursor: pointer; }
.yrS4-bubble-x:hover { color: #6b21a8; }
.yrS4-bubble-body { white-space: pre-wrap; overflow-wrap: anywhere; }
.yrS4-bubble-state { font-size: 11px; color: #6b7280; font-style: italic; }
.yrS4-bubble-acts { display: flex; gap: 4px 10px; align-items: center; flex-wrap: wrap; }
.yrS4-bubble-acts button { border: 0; background: transparent; color: #6b21a8; font: inherit; font-size: 11px; padding: 0; cursor: pointer; text-decoration: underline; text-underline-offset: 2px; }
.yrS4-bubble-acts button:hover { color: #3b0764; }
@media (prefers-color-scheme: dark) { .yrS4-bubble { background: #2a1a33; color: #e5e7eb; border-color: #6b21a8; } .yrS4-bubble-head { color: #d8b4fe; } .yrS4-bubble-acts button { color: #d8b4fe; } .yrS4-bubble-acts button:hover { color: #f3e8ff; } .yrS4-bubble-state { color: #9ca3af; } }
@media print { .yrS4-bubbles { display: none; } }
`

export interface BubbleHandlers {
  open(id: string): void          // the note's card in the panel
  hideAll(): void                 // the switch in the panel goes off (the frame owns it)
}

const WIDTH = 250
const GAP = 16                    // between the text and a bubble
const STACK = 8                   // between stacked bubbles
const MAX_BODY = 320

/** The state line under a note's text: what the AI did with it, or asked. */
function stateOf(m: MarkRow): string {
  const d = m.data as { applied?: { by?: string }; review?: { state?: string }; question?: string; answer?: { text?: string }; run?: { state?: string } }
  if (d.review?.state === 'accepted') return 'applied · accepted'
  if (d.review?.state === 'redo') return 'sent back for a redo'
  if (d.applied) return d.applied.by === 'ai' ? 'applied by the AI: review it in the panel' : 'applied'
  if (d.question) return d.answer?.text ? 'the AI asked; you answered' : 'the AI asks a question: answer it in the panel'
  if (d.run?.state === 'in-progress') return 'the AI is on it'
  if (d.run?.state === 'queued') return 'queued for the AI'
  if (d.run?.state === 'skipped') return 'skipped by the AI'
  if (m.status === 'exported') return 'exported in a packet'
  if (m.status === 'done') return 'done'
  return ''
}

export class NoteBubbles {
  private el: HTMLElement
  private hidden = new Set<string>()          // bubbles hidden one by one (this page view; a reload shows them again)
  private bubbles = new Map<string, HTMLElement>()
  private decor: HTMLElement[] = []           // tints, wires: rebuilt on every layout
  constructor(layer: HTMLElement, private h: BubbleHandlers) {
    this.el = document.createElement('div')
    this.el.className = 'yrS4-bubbles'
    this.el.setAttribute('role', 'region')
    this.el.setAttribute('aria-label', 'Editorial notes beside the text')
    layer.appendChild(this.el)
  }

  /** Hidden one by one (the "Hide" on the bubble): the note's hover card offers "Show bubble". */
  isHidden(id: string): boolean {
    return this.hidden.has(id)
  }
  show(id: string) {
    this.hidden.delete(id)
  }
  /** The switch went on again: every bubble comes back. */
  reset() {
    this.hidden.clear()
  }
  clear() {
    for (const b of this.bubbles.values()) b.remove()
    this.bubbles.clear()
    for (const d of this.decor) d.remove()
    this.decor = []
  }

  /** Draw (or move) the bubbles of the placed editorial notes. `on` false: none at all. Call on every redraw. */
  layout(placed: Placed[], contentRoot: HTMLElement, on: boolean, relayout: () => void) {
    for (const d of this.decor) d.remove()
    this.decor = []
    const notes = on ? placed.filter((p) => p.mark.kind === 'author_note' && !this.hidden.has(p.mark.id)) : []
    const seen = new Set<string>()
    const sx = window.scrollX, sy = window.scrollY
    const rootRect = contentRoot.getBoundingClientRect()
    const contentLeft = rootRect.left + sx, contentRight = rootRect.right + sx
    const vw = document.documentElement.clientWidth
    // the margin on the right: up to the book's own right sidebar ("On this page") when one is there, else the viewport
    const side = document.querySelector<HTMLElement>('#quarto-margin-sidebar, .bd-sidebar-secondary, #quarto-sidebar-toc, .bd-toc')
    const sideRect = side && side.offsetWidth > 0 ? side.getBoundingClientRect() : null
    const roomRight = (sideRect && sideRect.left > rootRect.right ? sideRect.left : vw) - rootRect.right
    const roomLeft = rootRect.left
    const where: 'right' | 'left' | 'inside' = roomRight >= WIDTH + GAP + 8 ? 'right' : vw - rootRect.right >= WIDTH + GAP + 8 ? 'right' : roomLeft >= WIDTH + GAP + 40 ? 'left' : 'inside'
    const items: Array<{ p: Placed; rects: DOMRect[]; top: number; bottom: number }> = []
    for (const p of notes) {
      const rects = p.element ? [p.element.getBoundingClientRect()] : Array.from(p.range.getClientRects()).filter((r) => r.width > 0 && r.height > 0)
      if (!rects.length) continue
      const top = Math.min(...rects.map((r) => r.top)) + sy
      const bottom = Math.max(...rects.map((r) => r.bottom)) + sy
      items.push({ p, rects, top, bottom })
    }
    items.sort((a, b) => a.top - b.top || a.bottom - b.bottom)
    let lastBottom = 0
    for (const it of items) {
      const m = it.p.mark
      seen.add(m.id)
      let b = this.bubbles.get(m.id)
      if (!b) {
        b = this.build(m, relayout)
        this.el.appendChild(b)
        this.bubbles.set(m.id, b)
      } else this.fill(b, m)
      b.className = `yrS4-bubble ${where}`
      b.style.width = `${WIDTH}px`
      const h = b.offsetHeight || 60
      const wantTop = where === 'inside' ? it.bottom + 6 : it.top - 6
      const top = Math.max(wantTop, lastBottom + STACK)
      let left: number
      if (where === 'right') left = contentRight + GAP
      else if (where === 'left') left = Math.max(4, contentLeft - GAP - WIDTH - 20)   // leave the margin lines free
      else left = Math.max(4, contentRight - WIDTH - 8)
      b.style.left = `${left}px`
      b.style.top = `${top}px`
      lastBottom = top + h
      // the tint over the passage, and the wire from the passage to the bubble
      for (const r of it.rects) this.decor.push(this.tintAt(r.left + sx, r.top + sy, r.width, r.height, m.id))
      if (where !== 'inside') {
        const first = it.rects[0]
        const y = Math.round(first.top + sy + Math.min(first.height, 24) / 2)
        const arrowY = top + 15                               // where the bubble's arrow sits
        if (where === 'right') {
          const x1 = first.right + sx + 2, x2 = left - 10
          if (Math.abs(arrowY - y) < 3) this.decor.push(this.wire(x1, y, x2 - x1))
          else {
            // an elbow: along the line, down (or up) beside the bubble, into the arrow
            const xe = left - 8
            this.decor.push(this.wire(x1, y, xe - x1 + 1), this.drop(xe, Math.min(y, arrowY), Math.abs(arrowY - y)), this.wire(xe, arrowY, left - 10 - xe))
          }
        } else {
          const x1 = first.left + sx - 2, x2 = left + WIDTH + 8
          if (Math.abs(arrowY - y) < 3) this.decor.push(this.wire(x2, y, x1 - x2))
          else {
            const xe = left + WIDTH + 8
            this.decor.push(this.wire(xe, y, x1 - xe), this.drop(xe, Math.min(y, arrowY), Math.abs(arrowY - y)))
          }
        }
      }
      // hovering the bubble lights the passage up; hovering the passage lights the bubble up is left out (the text stays the book's)
      const tints = this.decor.filter((d) => d.getAttribute('data-for') === m.id)
      b.onmouseenter = () => tints.forEach((t) => t.classList.add('hot'))
      b.onmouseleave = () => tints.forEach((t) => t.classList.remove('hot'))
    }
    for (const [id, b] of this.bubbles) {
      if (!seen.has(id)) {
        b.remove()
        this.bubbles.delete(id)
      }
    }
    this.el.hidden = !this.bubbles.size
  }

  private tintAt(x: number, y: number, w: number, h: number, id: string): HTMLElement {
    const d = document.createElement('div')
    d.className = 'yrS4-bubble-tint'
    d.setAttribute('data-for', id)
    d.style.cssText = `left:${x}px;top:${y}px;width:${w}px;height:${h}px`
    this.el.appendChild(d)
    return d
  }
  private wire(x: number, y: number, w: number): HTMLElement {
    const d = document.createElement('div')
    d.className = 'yrS4-bubble-wire'
    if (w < 0) { x += w; w = -w }
    d.style.cssText = `left:${x}px;top:${y}px;width:${Math.max(0, w)}px;height:0`
    this.el.appendChild(d)
    return d
  }
  private drop(x: number, y: number, h: number): HTMLElement {
    const d = document.createElement('div')
    d.className = 'yrS4-bubble-drop'
    d.style.cssText = `left:${x}px;top:${y}px;width:0;height:${Math.max(0, h)}px`
    this.el.appendChild(d)
    return d
  }

  private build(m: MarkRow, relayout: () => void): HTMLElement {
    const b = document.createElement('div')
    b.className = 'yrS4-bubble'
    b.setAttribute('data-id', m.id)
    b.setAttribute('role', 'note')
    const head = document.createElement('div')
    head.className = 'yrS4-bubble-head'
    head.innerHTML = '<span class="yrS4-bubble-kind"></span><span class="yrS4-bubble-prio"></span>'
    const x = document.createElement('button')
    x.type = 'button'
    x.className = 'yrS4-bubble-x'
    x.textContent = '×'
    x.title = 'Hide this bubble (the margin line stays; its card has "Show bubble")'
    x.setAttribute('aria-label', 'Hide this bubble')
    x.addEventListener('click', () => {
      this.hidden.add(m.id)
      relayout()
    })
    head.appendChild(x)
    b.appendChild(head)
    const body = document.createElement('div')
    body.className = 'yrS4-bubble-body'
    b.appendChild(body)
    const state = document.createElement('div')
    state.className = 'yrS4-bubble-state'
    b.appendChild(state)
    const acts = document.createElement('div')
    acts.className = 'yrS4-bubble-acts'
    const open = document.createElement('button')
    open.type = 'button'
    open.textContent = 'Open'
    open.title = 'The note\'s card in the panel: edit it, mark it done, see the AI\'s feedback'
    open.addEventListener('click', () => this.h.open(m.id))
    const all = document.createElement('button')
    all.type = 'button'
    all.textContent = 'Hide all bubbles'
    all.title = 'Hide every bubble; "Show my editorial notes" in the panel has the switch to bring them back'
    all.addEventListener('click', () => this.h.hideAll())
    acts.append(open, all)
    b.appendChild(acts)
    this.fill(b, m)
    return b
  }

  private fill(b: HTMLElement, m: MarkRow) {
    const cat = (m.data.category as string) || 'note'
    const prio = Number(m.data.priority) || 0
    b.querySelector('.yrS4-bubble-kind')!.textContent = `Editorial note · ${cat}`
    const pr = b.querySelector<HTMLElement>('.yrS4-bubble-prio')!
    pr.textContent = prio ? '●'.repeat(Math.min(3, prio)) + '○'.repeat(Math.max(0, 3 - prio)) : ''
    pr.title = prio ? `priority ${prio} of 3` : ''
    const body = b.querySelector<HTMLElement>('.yrS4-bubble-body')!
    const text = (m.body || '').trim()
    body.textContent = text.length > MAX_BODY ? text.slice(0, MAX_BODY).trimEnd() + '…' : text || '(no text)'
    const proposed = typeof m.data.proposed === 'string' && m.data.proposed.trim() ? m.data.proposed.trim() : ''
    const st = b.querySelector<HTMLElement>('.yrS4-bubble-state')!
    const parts = [stateOf(m), proposed ? 'has proposed text (Open)' : ''].filter(Boolean)
    st.textContent = parts.join(' · ')
    st.hidden = !parts.length
    b.setAttribute('aria-label', `Editorial note, ${cat}: ${text.slice(0, 120)}`)
  }
}
