// Hidden passages (docs/06a-labels.qmd "Hidden passages", D54): a mark carrying a hiding label takes its
// passage off the page for students and visitors, whatever the switches say; the label's owner and the owner's
// co-teachers (Q44) see it under a hatch. The frame says which marks hide for this viewer (`hides` on the marks message); this module
// removes the passages from the page and puts them back when the list changes, and draws the owner's hatched
// tint over a passage they hid (in the overlay layer: the book's text is never painted). A page's hides are
// remembered in the book origin's storage and applied at boot, so a repeat visit shows no flash of the hidden
// text while the frame answers. The text is still in the page's HTML: the overlay only removes it from the page.
import type { Anchor, ExceptPart, HiddenPassage } from '../../../shared/types.ts'
import type { HeadingInfo } from '../adapters/index.ts'
import type { Placed } from './margin.ts'
import { foldText } from '../../../shared/fold.ts'

export const HIDES_CSS = `
/* hidden passages (D54): the owner's hatch over a passage hidden from everyone else */
.yrS4-hides { position: absolute; left: 0; top: 0; width: 0; height: 0; overflow: visible; }
.yrS4-hide-tint { position: absolute; pointer-events: none; border-radius: 3px; background: repeating-linear-gradient(135deg, rgba(107, 114, 128, .16) 0 6px, rgba(107, 114, 128, .04) 6px 12px); box-shadow: inset 0 0 0 1px rgba(107, 114, 128, .35); }
.yrS4-hide-tag { position: absolute; pointer-events: none; font: 600 10px/1.4 system-ui, sans-serif; color: #374151; background: #f3f4f6; border: 1px solid #9ca3af; border-radius: 3px; padding: 0 5px; white-space: nowrap; }
`

const CACHE_PREFIX = 'yrS4-hides-'
const norm = foldText

export interface HideContext {
  root: HTMLElement
  headings: HeadingInfo[]
  /** The passage of an anchor on the page now (exact, or the fuzzy re-find the marks use). */
  find(anchor: Anchor): { range: Range; element?: HTMLElement } | null
  /** The block element a node sits in (the one with the checkbox). */
  blockOf(node: Node | null | undefined): HTMLElement | undefined
}

interface Removed { marker: HTMLElement; nodes: Node[] }

export class Hides {
  private wanted: HiddenPassage[] = []
  private applied = new Map<string, Removed[]>()
  private decor: HTMLElement
  constructor(layer: HTMLElement) {
    this.decor = document.createElement('div')
    this.decor.className = 'yrS4-hides'
    layer.appendChild(this.decor)
  }

  /** The hides for this viewer, from the frame (or the cache at boot). */
  set(list: HiddenPassage[]) {
    this.wanted = list
  }
  get list(): HiddenPassage[] {
    return this.wanted
  }
  isHidden(id: string): boolean {
    return this.applied.has(id)
  }

  /** Remove what is wanted and not yet removed, put back what is no longer wanted. True when the page changed. */
  reconcile(ctx: HideContext): boolean {
    let changed = false
    const want = new Set(this.wanted.map((h) => h.id))
    for (const id of [...this.applied.keys()]) {
      if (!want.has(id)) {
        this.restore(id)
        changed = true
      }
    }
    for (const h of this.wanted) {
      if (this.applied.has(h.id)) continue
      const removed = this.remove(h, ctx)
      if (removed.length) {
        this.applied.set(h.id, removed)
        changed = true
      }
    }
    return changed
  }

  restoreAll() {
    for (const id of [...this.applied.keys()]) this.restore(id)
  }

  private restore(id: string) {
    for (const r of this.applied.get(id) || []) {
      if (r.marker.isConnected) r.marker.before(...r.nodes)
      r.marker.remove()
    }
    this.applied.delete(id)
  }

  private marker(id: string): HTMLElement {
    const m = document.createElement('span')
    m.setAttribute('data-yrs4', 'hide')
    m.setAttribute('data-hide', id)
    m.hidden = true
    return m
  }

  /** Take the passage out of the page; the nodes are kept for a later restore. */
  private remove(h: HiddenPassage, ctx: HideContext): Removed[] {
    const anchor = h.anchor_current || h.anchor
    if (!anchor) return []
    const keep = this.keptParts(h.except, ctx)
    if (anchor.scope === 'page') {
      // everything but the title block, the navigation and the overlay's own elements
      const nodes = Array.from(ctx.root.childNodes).filter((n) => !(n.nodeType === 1 && (n as Element).matches('[data-yrs4], nav, header, #title-block-header, .quarto-title-block, h1, script, style')))
      return this.removeNodes(h.id, nodes, keep)
    }
    const found = ctx.find(anchor)
    if (!found) return []
    if (anchor.scope === 'section' && found.element) return this.removeNodes(h.id, [found.element], keep)
    // a block: the whole element when the range covers it; else (a text passage) the range's contents
    const block = ctx.blockOf(found.range.startContainer)
    if (block && norm(found.range.toString()) === norm(block.textContent || '')) return this.removeNodes(h.id, [block], keep)
    const marker = this.marker(h.id)
    const r = found.range
    r.insertNode(marker)
    r.setStartAfter(marker)
    const frag = r.extractContents()
    return [{ marker, nodes: Array.from(frag.childNodes) }]
  }

  /** Remove each node unless an excepted part is inside it; then go into that node and remove around the part. */
  private removeNodes(id: string, nodes: Node[], keep: Element[]): Removed[] {
    const out: Removed[] = []
    let run: Node[] = []
    let marker: HTMLElement | null = null
    const flush = () => {
      if (marker && run.length) out.push({ marker, nodes: run })
      else marker?.remove()
      run = []
      marker = null
    }
    for (const n of nodes) {
      const holds = n.nodeType === 1 && keep.some((k) => n === k || (n as Element).contains(k))
      if (holds) {
        flush()
        if (!keep.includes(n as Element)) out.push(...this.removeNodes(id, Array.from(n.childNodes), keep))   // around the kept part
        continue
      }
      if (!marker) {
        marker = this.marker(id)
        n.parentNode?.insertBefore(marker, n)
      }
      run.push(n)
      n.parentNode?.removeChild(n)
    }
    flush()
    return out
  }

  /** The elements of a hide's exceptions ("all of 8.4 except 8.4.2"): they stay on the page. */
  private keptParts(parts: ExceptPart[], ctx: HideContext): Element[] {
    const out: Element[] = []
    for (const x of parts || []) {
      if (x.scope === 'section' && x.section) {
        const want = x.section
        const h = (want.id && ctx.headings.find((y) => y.id === want.id)) || ctx.headings.find((y) => y.text.toLowerCase() === (want.headings.slice(-1)[0] || '').toLowerCase())
        if (h) out.push(h.section)
      } else if (x.quote) {
        const f = ctx.find({ scope: 'block', quote: x.quote, position: x.position, package: '', page: '' })
        const b = f && ctx.blockOf(f.range.startContainer)
        if (b) out.push(b)
      }
    }
    return out
  }

  // --- the owner's hatch ------------------------------------------------------------------------------------------
  /** A hatched tint and a small tag over every passage hidden from students and visitors that this viewer may see. */
  hatch(placed: Placed[]) {
    this.decor.replaceChildren()
    const sx = window.scrollX, sy = window.scrollY
    for (const p of placed) {
      if (p.mark.kind !== 'label' || !p.labels?.some((l) => l.hides)) continue   // own, or a co-teacher's (Q44)
      const rects = (p.element ? [p.element.getBoundingClientRect()] : Array.from(p.range.getClientRects())).filter((r) => r.width > 0 && r.height > 0)
      if (!rects.length) continue
      for (const r of rects) {
        const d = document.createElement('div')
        d.className = 'yrS4-hide-tint'
        d.style.cssText = `left:${r.left + sx}px;top:${r.top + sy}px;width:${r.width}px;height:${r.height}px`
        this.decor.appendChild(d)
      }
      const first = rects[0]
      const tag = document.createElement('span')
      tag.className = 'yrS4-hide-tag'
      tag.textContent = 'hidden from students and visitors'
      tag.style.cssText = `left:${Math.max(0, first.right + sx - 170)}px;top:${first.top + sy - 8}px`
      this.decor.appendChild(tag)
    }
  }
  clearHatch() {
    this.decor.replaceChildren()
  }

  // --- the cache (this book origin's storage, per page path) -----------------------------------------------------
  static readCache(path: string): HiddenPassage[] {
    try {
      const v = JSON.parse(localStorage.getItem(CACHE_PREFIX + path) || '[]')
      return Array.isArray(v) ? (v as HiddenPassage[]) : []
    } catch {
      return []
    }
  }
  static writeCache(path: string, list: HiddenPassage[]) {
    try {
      if (list.length) localStorage.setItem(CACHE_PREFIX + path, JSON.stringify(list))
      else localStorage.removeItem(CACHE_PREFIX + path)
    } catch { /* storage may be blocked */ }
  }
}
