// Character folding for finding a passage (docs/04-anchoring.qmd "Characters the renderer changes", D55): a
// quote typed from the source, or by hand, must find the rendered text although Quarto and Jupyter Book
// turn ' into ’, " into “ ”, -- into –, --- into —, ... into …, and insert non-breaking spaces. Both sides
// of every comparison go through this: the page text the page script extracts (and the CLI's copy of it,
// book-text/), the quote, prefix and suffix of an anchor, and the whitespace-collapsing `norm` helpers. The
// fold is only for finding: it changes nothing on the page. One raw character may fold to none ("…" is kept
// as three, a soft hyphen as none), so the page script maps each folded character back to its raw one.

const ONE: Record<string, string> = {
  '‘': "'", '’': "'", '‚': "'", '‛': "'", '′': "'", '´': "'", '`': "'",   // ‘ ’ ‚ ‛ ′ ´ `
  '“': '"', '”': '"', '„': '"', '‟': '"', '″': '"',                                   // “ ” „ ‟ ″
  '‐': '-', '‑': '-', '‒': '-', '–': '-', '—': '-', '―': '-', '−': '-',   // ‐ ‑ ‒ – — ― −
  '…': '...',                                                                                            // …
  '­': '', '​': '', '‌': '', '‍': '', '﻿': '', '⁠': '',                         // soft hyphen, zero-width
}

/** One character of page text, as it is compared: '' to drop it, several characters for one (…). */
export function foldChar(ch: string): string {
  const one = ONE[ch]
  if (one !== undefined) return one
  if (ch < '\u0080') return ch
  // compatibility forms: ligatures (ﬁ → fi), full-width letters, superscript digits; a space-like character stays a space
  const n = ch.normalize('NFKC')
  return /^\s$/.test(n) ? ' ' : n
}

/** A string as it is compared: folded, whitespace collapsed to one space, trimmed. */
export function foldText(s: string): string {
  return foldKeep(s).trim()
}
/** The same without the trim: for a prefix or suffix, whose space at the edge is part of the context. */
export function foldKeep(s: string): string {
  let out = ''
  for (const ch of s) out += foldChar(ch)
  return out.replace(/\s+/g, ' ')
}
