// The one menu for a passage (D51, docs/06a-labels.qmd "The menu"): opened by a right-click on a block or a
// heading, or by selecting text. A row of scope pills at the top says what the rows act on (the selection, each
// block it touches, the section, the page) and lets the reader widen or narrow it; a faint tint on the page shows
// the chosen scope. The rows come from the page script (boot.ts), grouped: actions, the labels at hand, the rest of
// the labels (in a list that scrolls), the tail. A row that cannot apply stays, dimmed and in italics, with its
// reason. The open menu takes the keyboard: ↑ ↓ move, ← → change the scope, Home/End, PageUp/PageDown, a letter
// jumps to the next label, Enter/Space chooses, Esc closes (B76).

export interface MenuScope {
  id: string
  name: string                 // the pill: "Selection", "Paragraph", "Code block", "Section 9e…", "Page"
  prefix?: string              // a muted word before the name: "Section", "Intro of" (the name is then the heading's text)
  rects: DOMRect[]             // what to tint (client coordinates), empty for none
}
export interface MenuRow {
  text: string
  color?: string               // a label's color dot
  disabled?: string            // the reason the row cannot apply (shown after the text; the row is not chosen)
  fn?: () => void
}
export interface MenuRows {
  main: MenuRow[]
  labels: MenuRow[]            // the labels at hand (D50)
  rest: MenuRow[]              // the rest of the viewer's labels, reached by scrolling
  tail: MenuRow[]
}
export interface MenuOpen {
  scopes: MenuScope[]
  scope: string                // id of the scope to start on
  rows: (scopeId: string) => MenuRows
  hint: string
  at?: { x: number; y: number }       // page coordinates (a right-click)
  near?: DOMRect                      // client rect of a selection: above it when there is room, else below
  focus: boolean                      // take the keyboard at once (a right-click); a selection keeps it until ↑ ↓ or Esc
  onClose?: (why: 'escape' | 'outside' | 'choice' | 'api') => void
}

export class Menu {
  el: HTMLElement
  private tint: HTMLElement
  private open_: MenuOpen | null = null
  private scopeId = ''
  private docKey = (e: KeyboardEvent) => this.onDocKey(e)
  constructor(private layer: HTMLElement) {
    this.el = document.createElement('div')
    this.el.className = 'yrS4-menu'
    this.el.hidden = true
    this.el.tabIndex = -1
    this.el.setAttribute('role', 'menu')
    this.tint = document.createElement('div')
    this.tint.className = 'yrS4-tint'
    this.tint.hidden = true
    layer.append(this.tint, this.el)
    this.el.addEventListener('keydown', (e) => this.onKey(e))
    this.el.addEventListener('mouseover', (e) => {
      const b = (e.target as Element).closest?.('button:not(.yrS4-pill)')
      if (b && !b.classList.contains('yrS4-disabled')) this.activate(b as HTMLButtonElement)
    })
    document.addEventListener('mousedown', (e) => {
      if (this.visible && !e.composedPath().includes(this.el)) this.hide('outside')
    })
  }
  get visible() { return !this.el.hidden }
  get scope() { return this.scopeId }

  open(o: MenuOpen) {
    this.open_ = o
    this.scopeId = o.scopes.some((s) => s.id === o.scope) ? o.scope : o.scopes[0]?.id || ''
    this.render()
    this.el.hidden = false
    this.place()
    this.sizeList()
    this.showTint()
    this.activate(null)
    document.addEventListener('keydown', this.docKey, true)
    if (o.focus) this.el.focus({ preventScroll: true })
  }
  hide(why: 'escape' | 'outside' | 'choice' | 'api' = 'api') {
    if (this.el.hidden) return
    this.el.hidden = true
    this.tint.hidden = true
    document.removeEventListener('keydown', this.docKey, true)
    if (this.el.contains(this.layer.getRootNode() instanceof ShadowRoot ? (this.layer.getRootNode() as ShadowRoot).activeElement : document.activeElement)) this.el.blur()
    const cb = this.open_?.onClose
    this.open_ = null
    cb?.(why)
  }
  setScope(id: string) {
    if (!this.open_ || id === this.scopeId || !this.open_.scopes.some((s) => s.id === id)) return
    this.scopeId = id
    const top = this.el.style.top, left = this.el.style.left
    this.render()
    this.el.style.top = top
    this.el.style.left = left
    this.sizeList()
    this.showTint()
    this.activate(null)
    this.el.focus({ preventScroll: true })
  }

  // --- drawing ---------------------------------------------------------------------------------------------------
  private render() {
    const o = this.open_!
    const m = this.el
    m.replaceChildren()
    if (o.scopes.length > 1) {
      const pills = document.createElement('div')
      pills.className = 'yrS4-menu-pills'
      for (const s of o.scopes) {
        const b = document.createElement('button')
        b.type = 'button'
        b.className = `yrS4-pill${s.id === this.scopeId ? ' on' : ''}`
        if (s.prefix) {
          const k = document.createElement('span')
          k.className = 'yrS4-pill-kind'
          k.textContent = s.prefix
          b.append(k, ' ', s.name)
        } else b.textContent = s.name
        b.title = `The rows act on: ${s.prefix ? s.prefix + ' ' : ''}${s.name}`
        b.addEventListener('mousedown', (e) => e.preventDefault())   // keeps the selection
        b.addEventListener('click', () => this.setScope(s.id))
        pills.appendChild(b)
      }
      m.appendChild(pills)
    }
    const rows = o.rows(this.scopeId)
    const add = (into: HTMLElement, r: MenuRow) => {
      const b = document.createElement('button')
      b.type = 'button'
      if (r.color) {
        const dot = document.createElement('span')
        dot.className = 'yrS4-menu-dot'
        dot.style.background = r.color
        b.append(dot, r.text)
      } else b.textContent = r.text
      if (r.disabled) {
        b.classList.add('yrS4-disabled')
        b.setAttribute('aria-disabled', 'true')
        const why = document.createElement('span')
        why.className = 'yrS4-menu-why'
        why.textContent = ` (${r.disabled})`
        b.appendChild(why)
      }
      b.addEventListener('mousedown', (e) => e.preventDefault())     // keeps the selection
      b.addEventListener('click', () => {
        if (r.disabled || !r.fn) return
        this.hide('choice')
        r.fn()
      })
      into.appendChild(b)
    }
    const sep = (into: HTMLElement) => {
      const s = document.createElement('div')
      s.className = 'yrS4-menu-sep'
      into.appendChild(s)
    }
    for (const r of rows.main) add(m, r)
    if (rows.labels.length || rows.rest.length) {
      if (rows.main.length) sep(m)
      const list = document.createElement('div')
      list.className = 'yrS4-menu-list'
      list.dataset.atHand = String(rows.labels.length)
      m.appendChild(list)
      for (const r of rows.labels) add(list, r)
      if (rows.rest.length) {
        if (rows.labels.length) sep(list)
        const more = document.createElement('div')
        more.className = 'yrS4-menu-hint'
        more.textContent = rows.labels.length ? 'the rest of your labels' : 'your labels'
        list.appendChild(more)
        for (const r of rows.rest) add(list, r)
      }
    }
    if (rows.tail.length) {
      sep(m)
      for (const r of rows.tail) add(m, r)
    }
    const hint = document.createElement('div')
    hint.className = 'yrS4-menu-hint'
    hint.textContent = o.hint
    m.appendChild(hint)
  }
  /** The list of labels is as tall as the labels at hand (at least three rows); the rest is reached by scrolling or the keys. */
  private sizeList() {
    const list = this.el.querySelector<HTMLElement>('.yrS4-menu-list')
    if (!list) return
    list.style.maxHeight = ''
    const atHand = Number(list.dataset.atHand || 0)
    const rows = [...list.querySelectorAll<HTMLElement>('button')]
    if (rows.length <= atHand) return
    const last = rows[Math.min(rows.length, Math.max(atHand, 3)) - 1]
    if (last) list.style.maxHeight = `${last.offsetTop + last.offsetHeight - list.offsetTop + 2}px`
  }
  private place() {
    const o = this.open_!
    const m = this.el
    const vw = document.documentElement.clientWidth, vh = document.documentElement.clientHeight
    const w = m.offsetWidth || 240, h = m.offsetHeight || 200
    if (o.at) {
      m.style.left = `${Math.max(window.scrollX + 8, Math.min(o.at.x, window.scrollX + vw - w - 8))}px`
      let top = o.at.y
      if (o.at.y - window.scrollY + h > vh - 8 && o.at.y - h >= window.scrollY + 8) top = o.at.y - h   // no room below: open upward
      m.style.top = `${top}px`
    } else if (o.near) {
      // the toolbar's rule: centered on the passage, above it when there is room, else below
      const r = o.near
      let left = r.left + window.scrollX + r.width / 2 - w / 2
      left = Math.max(window.scrollX + 8, Math.min(left, window.scrollX + vw - w - 8))
      let top = r.top + window.scrollY - h - 8
      if (r.top - h - 8 < 4) top = r.bottom + window.scrollY + 8
      m.style.left = `${left}px`
      m.style.top = `${top}px`
    }
  }
  private showTint() {
    const s = this.open_?.scopes.find((x) => x.id === this.scopeId)
    this.tint.replaceChildren()
    if (!s || !s.rects.length) {
      this.tint.hidden = true
      return
    }
    for (const r of s.rects) {
      const d = document.createElement('div')
      d.style.left = `${r.left + window.scrollX}px`
      d.style.top = `${r.top + window.scrollY}px`
      d.style.width = `${r.width}px`
      d.style.height = `${r.height}px`
      this.tint.appendChild(d)
    }
    this.tint.hidden = false
  }

  // --- the keyboard ----------------------------------------------------------------------------------------------
  private rows(): HTMLButtonElement[] {
    return [...this.el.querySelectorAll<HTMLButtonElement>('button:not(.yrS4-pill):not(.yrS4-disabled)')]
  }
  private activate(b: HTMLButtonElement | null, scroll = false) {
    for (const r of this.el.querySelectorAll('button')) r.classList.toggle('yrS4-active', r === b)
    if (b && scroll) b.scrollIntoView({ block: 'nearest' })
  }
  /** While a selection-opened menu does not hold the focus: plain ↑ ↓ take it (Shift+arrows still extend the selection), Esc closes. */
  private onDocKey(e: KeyboardEvent) {
    if (!this.visible || e.composedPath().includes(this.el)) return
    if (e.key === 'Escape') {
      this.hide('escape')
      e.preventDefault()
      return
    }
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && !e.shiftKey && !e.ctrlKey && !e.metaKey && !e.altKey) {
      this.el.focus({ preventScroll: true })
      this.onKey(e)
    }
  }
  private onKey(e: KeyboardEvent) {
    const rows = this.rows()
    const cur = rows.findIndex((r) => r.classList.contains('yrS4-active'))
    const go = (i: number) => rows.length && this.activate(rows[(i + rows.length) % rows.length], true)
    const scopes = this.open_?.scopes || []
    const si = scopes.findIndex((s) => s.id === this.scopeId)
    switch (e.key) {
      case 'ArrowDown': go(cur + 1); break
      case 'ArrowUp': go(cur < 0 ? rows.length - 1 : cur - 1); break
      case 'ArrowRight': if (si >= 0 && si + 1 < scopes.length) this.setScope(scopes[si + 1].id); break
      case 'ArrowLeft': if (si > 0) this.setScope(scopes[si - 1].id); break
      case 'Home': go(0); break
      case 'End': go(rows.length - 1); break
      case 'PageDown': go(Math.min(rows.length - 1, Math.max(cur, 0) + 5)); break
      case 'PageUp': go(Math.max(0, cur - 5)); break
      case 'Enter': case ' ': if (cur >= 0) rows[cur].click(); break
      case 'Escape': this.hide('escape'); break
      case 'Tab': this.hide('escape'); return
      default: {
        if (e.key.length !== 1 || e.ctrlKey || e.metaKey || e.altKey) return
        const k = e.key.toLowerCase()
        const name = (r: HTMLButtonElement) => (r.textContent || '').replace(/^(Apply|Remove) "/, '').toLowerCase()
        const next = rows.slice(cur + 1).concat(rows.slice(0, cur + 1)).find((r) => r.querySelector('.yrS4-menu-dot') && name(r).startsWith(k))
        if (!next) return
        this.activate(next, true)
      }
    }
    e.preventDefault()
    e.stopPropagation()
  }
}
