// The actions a passage offers (the rows of the menu, D51; docs/06a-labels.qmd) and the heading buttons. The lists
// below are the one place the demo registry reads (cli/src/demo-book.test.ts claims every `label:` here).
import type { CoverageStatus, LabelInfo, MarkKind } from '../../../shared/types.ts'

export interface ToolbarAction {
  kind: MarkKind | 'ask'
  status?: CoverageStatus
  data?: Record<string, unknown>
  label: string
  icon: string
  cls: string
  color?: string            // label chips
}

/** One chip per label, most recent first (up to `max`), then "More…" which opens the picker in the panel. (The menu's
 *  label rows come from the state's `menuLabels` instead, D50; this stays for the heading buttons.) */
export function labelActions(labels: LabelInfo[], max = 6): ToolbarAction[] {
  const mine = labels.filter((l) => l.mine)
  const chips: ToolbarAction[] = mine.slice(0, max).map((l) => ({ kind: 'label', data: { labels: [l.id] }, label: l.name, icon: '●', cls: 'labelchip', color: l.color }))
  chips.push({ kind: 'label', data: {}, label: mine.length > max ? 'More…' : 'New label…', icon: '＋', cls: 'more' })
  return chips
}

