/** Small "Mark this section" buttons shown beside a heading on hover (teach mode). */
export class HeadingButtons {
  private el: HTMLElement
  private current: HTMLElement | null = null
  constructor(layer: HTMLElement, private onPick: (a: ToolbarAction, heading: HTMLElement) => void) {
    this.el = document.createElement('div')
    this.el.className = 'yrS4-headbtns'
    this.el.hidden = true
    layer.appendChild(this.el)
    this.el.addEventListener('mouseleave', () => this.scheduleHide())
    this.el.addEventListener('mouseenter', () => this.cancelHide())
  }
  private hideTimer: number | undefined
  private scheduleHide() {
    this.cancelHide()
    this.hideTimer = window.setTimeout(() => this.hide(), 400)
  }
  private cancelHide() {
    if (this.hideTimer) clearTimeout(this.hideTimer)
    this.hideTimer = undefined
  }

  attach(headings: HTMLElement[], actions: ToolbarAction[]) {
    this.el.replaceChildren()
    const label = document.createElement('span')
    label.className = 'yrS4-headbtns-label'
    label.textContent = 'This section:'
    this.el.appendChild(label)
    for (const a of actions) {
      const b = document.createElement('button')
      b.type = 'button'
      b.className = `yrS4-tb yrS4-tb-${a.cls}`
      b.title = `${a.label} (whole section)`
      b.innerHTML = `<span class="yrS4-tb-icon"${a.color ? ` style="color:${a.color}"` : ''}>${a.icon}</span>`
      b.addEventListener('click', (e) => {
        e.preventDefault()
        if (this.current) this.onPick(a, this.current)
        this.hide()
      })
      this.el.appendChild(b)
    }
    for (const h of headings) {
      if ((h as { __yrS4?: boolean }).__yrS4) continue
      ;(h as { __yrS4?: boolean }).__yrS4 = true
      h.addEventListener('mouseenter', () => this.showFor(h))
      h.addEventListener('mouseleave', () => this.scheduleHide())
    }
  }
  private enabled = false
  setEnabled(on: boolean) {
    this.enabled = on
    if (!on) this.hide()
  }
  private showFor(h: HTMLElement) {
    if (!this.enabled) return
    this.cancelHide()
    this.current = h
    const r = h.getBoundingClientRect()
    this.el.hidden = false
    this.el.style.top = `${r.top + window.scrollY + r.height / 2 - this.el.offsetHeight / 2}px`
    const right = r.right + window.scrollX + 8
    const maxLeft = window.scrollX + document.documentElement.clientWidth - this.el.offsetWidth - 8
    this.el.style.left = `${Math.min(right, maxLeft)}px`
  }
  hide() {
    this.el.hidden = true
    this.current = null
  }
}
