// In-place edits (docs/07-author-notes.qmd "In-place edits", D40): a teacher's proposal for a block is shown on
// the page in place of the block, for the teacher who wrote it. The original HTML is kept and restored when the
// edit is hidden, deleted, or the page is re-drawn without it. The source files are never touched.

interface Applied { el: HTMLElement; original: string; html: string }

export class Edits {
  private applied = new Map<string, Applied>()   // mark id → block
  private lastEl = new Map<string, HTMLElement>()  // where an edit was last shown (for "Original" while pressed)
  suppressed = new Set<string>()                 // edits showing their original for the moment

  has(id: string) {
    return this.applied.has(id)
  }
  elementOf(id: string): HTMLElement | undefined {
    return this.applied.get(id)?.el
  }
  originalTextOf(id: string): string {
    const a = this.applied.get(id)
    if (!a) return ''
    const t = document.createElement('div')
    t.innerHTML = a.original
    return (t.textContent || '').replace(/\s+/g, ' ').trim()
  }

  /** Show `html` (already sanitized by the frame) in place of the block's content. */
  apply(id: string, el: HTMLElement, html: string) {
    const cur = this.applied.get(id)
    if (cur && cur.el === el && cur.html === html) return
    if (cur) this.restore(id)
    const original = el.innerHTML
    el.setAttribute('data-yrs4', 'edit')            // the overlay ignores the block's text while the edit shows
    el.setAttribute('data-yrs4-edit', id)
    // the proposal is a whole block of Markdown; a single <p> replaces a paragraph's own content, otherwise the
    // block holds the rendered blocks as they are
    const t = document.createElement('div')
    t.innerHTML = html
    const one = t.children.length === 1 ? t.firstElementChild! : null
    if (el.tagName === 'P' && one?.tagName === 'P') el.innerHTML = one.innerHTML
    // a heading keeps its own element (its level, id and section), its number and its header link: the
    // proposal's heading or paragraph gives the words (B74)
    else if (/^H[1-6]$/.test(el.tagName) && one && /^(H[1-6]|P)$/.test(one.tagName)) {
      const kids = Array.from(el.children)
      const num = kids.filter((c) => c.matches('.section-number, .header-section-number, .chapter-number'))
      const link = kids.filter((c) => c.matches('.headerlink, .anchorjs-link'))
      el.innerHTML = one.innerHTML
      if (num.length) el.prepend(...num, document.createTextNode(' '))
      el.append(...link)
    } else el.innerHTML = html
    this.applied.set(id, { el, original, html })
    this.lastEl.set(id, el)
  }
  lastElementOf(id: string): HTMLElement | undefined {
    const el = this.lastEl.get(id)
    return el && el.isConnected ? el : undefined
  }

  restore(id: string) {
    const a = this.applied.get(id)
    if (!a) return
    if (a.el.isConnected) {
      a.el.innerHTML = a.original
      a.el.removeAttribute('data-yrs4')
      a.el.removeAttribute('data-yrs4-edit')
    }
    this.applied.delete(id)
  }
  restoreAll() {
    for (const id of [...this.applied.keys()]) this.restore(id)
  }
  /** Keep only these ids applied. */
  keep(ids: Set<string>) {
    for (const id of [...this.applied.keys()]) if (!ids.has(id)) this.restore(id)
  }
}
