// The plain-HTML adapter (`generator: other`): any page with a <main>, else <body>.
import { OVERLAY_IGNORE, afterQuiet, type BookAdapter, type Container, type HeadingInfo } from './types.ts'

export const plain: BookAdapter = {
  name: 'other',
  detect: () => true,
  contentRoot: () => (document.querySelector('main') as HTMLElement) || (document.querySelector('article') as HTMLElement) || document.body,
  ignore: [...OVERLAY_IGNORE, 'nav', 'header', 'footer', 'button'],
  headings(): HeadingInfo[] {
    const root = this.contentRoot()
    const out: HeadingInfo[] = []
    for (const h of Array.from(root.querySelectorAll<HTMLElement>('h1, h2, h3, h4, h5, h6'))) {
      if (h.closest('nav, [data-yrs4]')) continue
      const section = (h.closest('section[id]') as HTMLElement) || h.parentElement || root
      const text = (h.textContent || '').replace(/\s+/g, ' ').trim()
      if (!text) continue
      out.push({ id: h.id || section.id || '', text, level: Number(h.tagName[1]), element: h, section })
    }
    return out
  },
  containers(): Container[] {
    return Array.from(this.contentRoot().querySelectorAll<HTMLDetailsElement>('details')).map((d) => ({
      element: d, header: d.querySelector<HTMLElement>('summary') || d, isOpen: () => d.open, open: () => { d.open = true },
    }))
  },
  sidebarLinks: () => new Map(),
  settled: () => afterQuiet(() => document.body, 200),
  blockKind(node: Node) {
    const el = node.nodeType === 1 ? (node as Element) : node.parentElement
    if (!el) return 'prose'
    if (el.closest('pre, code')) return 'code'
    if (el.closest('table')) return 'table'
    if (el.closest('figure')) return 'figure'
    return 'prose'
  },
}
