// Painting on the text itself is used for one thing only: the brief flash when a mark is jumped to from the
// panel (D36: marks show as margin lines, never as colored text). CSS Custom Highlight API; <mark> wrapping as
// the fallback (docs/03-architecture.qmd).
import type { CoverageStatus, MarkKind } from '../../../shared/types.ts'

export type PaintClass = 'covered' | 'assigned' | 'skipped' | 'comment' | 'note' | 'student' | 'edit' | 'flash' | `l-${string}`

/** The class a mark is drawn under (its margin line and legend entry). */
export function paintClassFor(kind: MarkKind, data: Record<string, unknown>): PaintClass | null {
  if (kind === 'label') {
    const first = ((data.labels as string[]) || [])[0]
    return first ? `l-${first}` : null
  }
  if (kind === 'coverage') return (data.status as CoverageStatus) || 'covered'
  if (kind === 'comment') return 'comment'
  if (kind === 'author_note') return 'note'
  if (kind === 'student_note') return 'student'
  if (kind === 'suggestion') return 'edit'
  return null
}

const STYLE_ID = 'yrS4-highlight-style'

/** The highlight rule must live in the document's own stylesheet, not the shadow root. */
export function installHighlightStyles() {
  if (document.getElementById(STYLE_ID)) return
  const s = document.createElement('style')
  s.id = STYLE_ID
  s.setAttribute('data-yrs4', '')
  s.textContent = `
::highlight(yrS4-flash) { background-color: rgba(255, 193, 7, 0.6); }
mark.yrS4-mark { background: transparent; color: inherit; padding: 0; }
mark.yrS4-mark.yrS4-flash { background-color: rgba(255, 193, 7, 0.6); }
`
  document.head.appendChild(s)
}

export const hasHighlightApi = typeof CSS !== 'undefined' && 'highlights' in CSS && typeof (globalThis as { Highlight?: unknown }).Highlight === 'function'

export class Painter {
  private fallbackMarks: HTMLElement[] = []
  private painted = new Set<string>()

  clear() {
    if (hasHighlightApi) {
      for (const c of this.painted) CSS.highlights.delete(`yrS4-${c}`)
      this.painted.clear()
    } else {
      for (const m of this.fallbackMarks) {
        const p = m.parentNode
        if (!p) continue
        while (m.firstChild) p.insertBefore(m.firstChild, m)
        p.removeChild(m)
        p.normalize()
      }
      this.fallbackMarks = []
    }
  }

  paint(groups: Map<PaintClass, Range[]>) {
    if (hasHighlightApi) {
      for (const [c, ranges] of groups) {
        if (!ranges.length) continue
        const H = (globalThis as unknown as { Highlight: new (...r: Range[]) => Highlight }).Highlight
        const h = new H(...ranges)
        h.priority = 10
        CSS.highlights.set(`yrS4-${c}`, h)
        this.painted.add(c)
      }
      return
    }
    for (const [c, ranges] of groups) for (const r of ranges) this.wrap(r, c)
  }

  /** Fallback: wrap the text nodes of a range in <mark> elements (changes the DOM; browsers without the API only). */
  private wrap(range: Range, cls: PaintClass) {
    const nodes: Text[] = []
    const w = document.createTreeWalker(range.commonAncestorContainer, NodeFilter.SHOW_TEXT)
    let n: Node | null = w.currentNode.nodeType === Node.TEXT_NODE ? w.currentNode : w.nextNode()
    while (n) {
      if (range.intersectsNode(n)) nodes.push(n as Text)
      n = w.nextNode()
    }
    for (const t of nodes) {
      let node = t
      if (node === range.startContainer && range.startOffset > 0) node = node.splitText(range.startOffset)
      if (node === range.endContainer || t === range.endContainer) {
        const endOff = t === range.endContainer ? range.endOffset - (node === t ? 0 : range.startOffset) : node.data.length
        if (endOff < node.data.length && endOff > 0) node.splitText(endOff)
      }
      if (!node.data.trim()) continue
      const m = document.createElement('mark')
      m.className = `yrS4-mark yrS4-${cls}`
      m.setAttribute('data-yrs4', '')
      node.parentNode?.insertBefore(m, node)
      m.appendChild(node)
      this.fallbackMarks.push(m)
    }
  }
}
